qualities = {'public': True, 'staffed': False, 'well lit': True, 'busy at meeting time': True, 'easy to leave': True}
score = sum(1 for v in qualities.values() if v)
print('safe qualities:', score, 'of', len(qualities))
for k, v in qualities.items():
    print(k + ':', 'yes' if v else 'NO')
print('verdict:', 'meet as planned' if score == 5 else ('daylight only, tell someone' if score >= 3 else 'propose a safe alternative or abandon'))

